import { describe, expect, it } from "vitest";
import { randomUUID } from "node:crypto";
import {
  createIsolatedDatabase,
  databaseTestsEnabled,
} from "./helpers/foundation-db";

describe.runIf(databaseTestsEnabled)("additive lifecycle migration", () => {
  it("preserves pending deletion and billing history while snapshotting original approval", async () => {
    const fixture = await createIsolatedDatabase();
    try {
      const migration = "20261020030000_subscription_lifecycle";
      for (const name of fixture.migrations.filter((name) => name < migration))
        await fixture.apply(name);
      const owner = randomUUID(),
        template = randomUUID(),
        contact = randomUUID(),
        campaign = randomUUID(),
        billing = randomUUID();
      const requestedAt = new Date("2026-01-01T00:00:00Z");
      await fixture.client.query(
        'INSERT INTO "User" (id,email,"deletionRequestedAt") VALUES ($1,$2,$3)',
        [owner, "[REDACTED_EMAIL]", requestedAt],
      );
      await fixture.client.query(
        "INSERT INTO \"Template\" (id,\"userId\",name,subject,body) VALUES ($1,$2,'Name','Subject','Body')",
        [template, owner],
      );
      await fixture.client.query(
        "INSERT INTO \"Contact\" (id,\"userId\",name,email) VALUES ($1,$2,'Ada','[REDACTED_EMAIL]')",
        [contact, owner],
      );
      await fixture.client.query(
        'INSERT INTO "Campaign" (id,"userId","templateId",status) VALUES ($1,$2,$3,\'QUEUED\')',
        [campaign, owner, template],
      );
      await fixture.client.query(
        'INSERT INTO "Send" (id,"campaignId","contactId","recipientRole") VALUES ($1,$2,$3,\'Research Wizard\')',
        [randomUUID(), campaign, contact],
      );
      await fixture.client.query(
        'INSERT INTO "BillingSubscription" (id,"userId","ownerIdSnapshot","dodoSubscriptionId","dodoCustomerId","productId",status,"updatedAt") VALUES ($1,$2,$2,\'sub_fixture\',\'cus_fixture\',\'pdt_fixture\',\'CANCELLED\',NOW())',
        [billing, owner],
      );
      await fixture.apply(migration);
      expect(
        (
          await fixture.client.query(
            'SELECT "deletionRequestedAt" FROM "User" WHERE id=$1',
            [owner],
          )
        ).rows[0].deletionRequestedAt,
      ).toEqual(requestedAt);
      expect(
        (
          await fixture.client.query(
            'SELECT "approvedRecipientCount", "usesCustomRole" FROM "Campaign" WHERE "userId"=$1',
            [owner],
          )
        ).rows[0],
      ).toEqual({ approvedRecipientCount: 1, usesCustomRole: true });
      expect(
        (
          await fixture.client.query(
            'SELECT status FROM "BillingSubscription" WHERE "userId"=$1',
            [owner],
          )
        ).rows[0].status,
      ).toBe("CANCELLED");
    } finally {
      await fixture.cleanup();
    }
  });
});
